// Declare constants in the global scope
const menuToggle = document.getElementById('menu-toggle');
const mouseTarget = document.getElementById("mouseTarget");
const rowId = document.getElementById("rowid");
const footer = document.querySelector("footer");
const socialElements = document.getElementById("social_elements2");

let slideIndex = 1; // Declare slideIndex at the top of your script


// Function to scale menu on window resize
// Function to check if any lightbox is open based on its inline style
function scale(x) {
    const menuToggle = document.getElementById('menu-toggle');

    // Query for any lightbox that has its style set to display: flex
    const anyLightboxOpen = document.querySelector("[id^='Lightbox_'][style*='display: flex']");

    // Only show the menu-toggle if no lightbox is open and the media query matches
    if (x.matches && !anyLightboxOpen) {
        menuToggle.style.display = 'flex';
    } else {
        menuToggle.style.display = 'none';
    }
}

// Set up MutationObserver to detect changes in the style attribute of lightboxes
const observer = new MutationObserver((mutationsList) => {
    mutationsList.forEach((mutation) => {
        if (mutation.type === 'attributes' && mutation.attributeName === 'style') {
            // If the style of a lightbox changes, re-check the menu toggle
            scale(window.matchMedia("(max-width: 1000px)"));
        }
    });
});

// Start observing all lightboxes for changes in the 'style' attribute
document.querySelectorAll("[id^='Lightbox_']").forEach((lightbox) => {
    observer.observe(lightbox, { attributes: true });
});

// Run initial check when the script loads
const x = window.matchMedia("(max-width: 1000px)");
scale(x);
x.addEventListener("change", () => scale(x)); // Attach listener function on state changes



// Function to open the lightbox
function openLightbox(lightboxId) {

    slideIndex = parseInt(sessionStorage.getItem(`slideIndex_${lightboxId}`)) || 1;
    console.log(`Opening Lightbox ${lightboxId} starting from slide ${slideIndex}`);

    console.log("Opening lightbox with id:", lightboxId); // Log the full ID string
    // Try to find the lightbox element using the full ID
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);

    // Check if the lightbox element is found
    if (!lightbox) {
        console.error(`Lightbox with ID ${lightboxId} not found.`);
        return; // Exit early if the lightbox is not found
    }

    // Perform further operations on the lightbox
    console.log("Found lightbox:", lightbox);

    // Load media for the lightbox
    loadMedia(lightboxId);

    // Store the current scroll position before opening the lightbox
    sessionStorage.setItem("scrollPosition", window.scrollY);

    // Hide all lightboxes except the one we are opening
    document.querySelectorAll("[id^='Lightbox_']").forEach(lightbox => {
        if (lightbox.id !== `Lightbox_${lightboxId}`) {
            lightbox.style.display = "none";
        }
    });

    if (!lightbox) {
        console.error(`Lightbox with ID ${lightboxId} not found.`);
        return; // Exit early if lightbox is not found
    }
    const projectTitle = document.getElementById(`projecttitle_${lightboxId}`);

    lightbox.style.display = "flex";
    projectTitle.style.display = "block";
    mouseTarget.style.display = "none";
    rowId.style.display = "none";
    footer.style.display = "none";
    socialElements.style.display = "none";
    menuToggle.style.display = "none";

    document.body.style.overflow = "hidden";

    // Set up the keys for navigating slides
    setKeys(lightboxId);

    // Retrieve the last slide index from sessionStorage
    const lastSlide = sessionStorage.getItem(`lastSlide_${lightboxId}`);

    // If the lightbox is being opened for the first time, initialize the slides
    if (!lastSlide) {
        toSlide(lightboxId, 0); // Start from the first slide (index 0)
    } else {
        toSlide(lightboxId, parseInt(lastSlide)); // Go to the last known slide
    }
}



// Function to close the lightbox
function closeLightbox(lightboxId) {
    // Store elements locally in the function, still using global constants
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const projectTitle = document.getElementById(`projecttitle_${lightboxId}`);

    // Reset styles to their default values for closing the lightbox
    lightbox.style.display = "none";
    projectTitle.style.display = "none";
    mouseTarget.style.display = "flex";
    rowId.style.display = "grid";
    footer.style.display = "flex";
    socialElements.style.display = "";
    menuToggle.style.display = "";

    document.body.style.overflow = ""; // Reset body overflow

    // Restore the scroll position to where it was before the lightbox opened
    const scrollPosition = sessionStorage.getItem("scrollPosition");
    if (scrollPosition) {
        window.scrollTo(0, parseInt(scrollPosition)); // Scroll to the stored position
    }
}

// Function to load media when lightbox is opened
function loadMedia(lightboxId) {
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);
    const modalContent = lightbox.querySelector(".modal-content");

    if (!modalContent) return;

    // Fetch media from the server if not cached
    const folderName = `lightbox_${lightboxId}`;
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName here as well
    fetchMediaData(folderName, lightboxId); // Pass folderName and lightboxId
}


// Function to fetch media data
function fetchMediaData(folderName, lightboxId, retries = 3) {
    console.log(`Fetching media for folder: ${folderName}`); // Log the folderName being passed

    // Check if the media for this lightbox is already present in the DOM
    const existingMedia = document.querySelector(`#Lightbox_${lightboxId} .image-slide`);

    if (existingMedia) {
        // Media already present in the DOM, so no need to fetch again
        console.log("Media already present in the DOM, skipping fetch.");
        return; // No need to fetch again
    }

    // If media is not present in the DOM, fetch it from the server
    fetch(`https://olgaamaya-y53u.onrender.com/api/get-cloudinary-media?folder=${folderName}`)
        .then((response) => response.json())
        .then((mediaFiles) => {
            console.log("Fetched media files:", mediaFiles);

            if (mediaFiles.length > 0) {
                // Insert the fetched media into the DOM
                displayMediaFiles(lightboxId, mediaFiles, folderName); // Pass lightboxId, mediaFiles, and folderName
            }
        })
        .catch((err) => {
            console.error("Error loading media:", err);
            if (retries > 0) {
                console.log(`Retrying... Remaining retries: ${retries}`);
                setTimeout(() => fetchMediaData(folderName, lightboxId, retries - 1), 2000);
            } else {
                alert(`Error loading media for Lightbox ${lightboxId}: ${err.message}`);
            }
        });
}



function displayMediaFiles(lightboxId, mediaFiles, folderName) {
    // Get the lightbox by its ID
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);

    if (!lightbox) {
        console.error(`Lightbox with ID ${lightboxId} not found.`);
        return;
    }

    // Now, query for the modal-content inside the lightbox
    const modalContent = lightbox.querySelector('.modal-content');

    if (!modalContent) {
        console.error(`Modal content not found inside lightbox with ID ${lightboxId}.`);
        return;
    }

    // Hide all previously inserted media (with the class ".image-slide" for images)
    const existingMedia = modalContent.querySelectorAll('.image-slide, .video');
    existingMedia.forEach((media) => {
        media.style.display = 'none'; // Hide existing images and videos
    });

    // Create slides for all media files (images only)
    mediaFiles.forEach((file, index) => {
        if (file.type === "image") {
            const slideDiv = document.createElement('div');
            slideDiv.classList.add('slide', `slide${lightboxId}`);

            // Create the image element
            const mediaElement = document.createElement('img');
            mediaElement.src = file.src;
            mediaElement.alt = file.alt;
            mediaElement.classList.add('image-slide');
            mediaElement.style.width = '100%';
            mediaElement.style.height = '100%';

            slideDiv.appendChild(mediaElement);

            // Assign the appropriate class based on the index (first, next, previous)
            if (index === 0) {
                slideDiv.classList.add('active-slide');
                slideDiv.style.display = 'flex'; // Active slide
            } else if (index === 1) {
                slideDiv.classList.add('next-slide');
                slideDiv.style.display = 'flex'; // Next slide
            } else if (index === mediaFiles.length - 1) {
                slideDiv.classList.add('previous-slide');
                slideDiv.style.display = 'flex'; // Previous slide
            } else {
                slideDiv.style.display = 'none'; // Hide all other slides initially
            }

            // Append the new slide to the modal content
            modalContent.appendChild(slideDiv);
        }
    });

    // After slides are added, set the active, next, and previous classes
    const startingSlideIndex = sessionStorage.getItem(`lastSlideIndex_${lightboxId}`) || 0;
    setActiveSlide(lightboxId, startingSlideIndex);

    // Ensure the slides are working properly by pausing videos if they're not active
    const slides = lightbox.querySelectorAll('.slide');
    slides.forEach(slide => {
        const video = slide.querySelector('video');
        if (video && !slide.classList.contains('active-slide')) {
            video.pause(); // Pause video if it's not the active slide
        }
    });
}

// Update the setActiveSlide function to include stopping videos when switching slides
function setActiveSlide(lightboxId, currentIndex) {
    // Get the lightbox element by its ID
    const lightbox = document.getElementById(`Lightbox_${lightboxId}`);

    if (!lightbox) return; // Exit if lightbox is not found

    // Get all slides inside the specific lightbox
    const slides = lightbox.getElementsByClassName('slide');

    const totalSlides = slides.length;

    // If no slides are found, exit the function
    if (totalSlides === 0) return;

    // Remove any previous active/next/previous classes and hide all slides
    Array.from(slides).forEach((slide) => {
        slide.classList.remove('active-slide', 'next-slide', 'previous-slide');
        slide.style.display = 'none'; // Hide all slides initially

        // Stop the video if it's not the active slide
        const video = slide.querySelector('video');
        if (video) {
            video.pause(); // Pause video when it's not active
        }
    });

    // Add active, next, and previous classes to the appropriate slides
    const previousIndex = (currentIndex - 1 + totalSlides) % totalSlides;
    const nextIndex = (currentIndex + 1) % totalSlides;

    // Assign active class to the current slide
    slides[currentIndex].style.display = 'flex';
    slides[currentIndex].classList.add('active-slide');

    // Assign previous class to the previous slide
    slides[previousIndex].style.display = 'flex';
    slides[previousIndex].classList.add('previous-slide');

    // Assign next class to the next slide
    slides[nextIndex].style.display = 'flex';
    slides[nextIndex].classList.add('next-slide');

    // Store the last slide index in sessionStorage
    sessionStorage.setItem(`lastSlideIndex_${lightboxId}`, currentIndex);
}


function storeLastSlide(lightboxId, slideIndex) {
    sessionStorage.setItem(`slideIndex_${lightboxId}`, slideIndex);
}

// Function to navigate to a specific slide
function toSlide(lightboxId, slideIndex) {
    setActiveSlide(lightboxId, slideIndex);
    storeLastSlide(lightboxId, slideIndex);
}
// Function to show a specific slide with display: flex and manage the slide state
function showSlide(lightboxId, slideIndex) {
    const slides = document.querySelectorAll(`#${lightboxId} .slide`);
    const totalSlides = slides.length;

    // Wrap slideIndex if it is out of bounds
    if (slideIndex > totalSlides) slideIndex = 1;
    else if (slideIndex < 1) slideIndex = totalSlides;

    // Remove any previous active/next/previous classes
    slides.forEach((slide) => {
        slide.style.display = "none"; // Hide all slides initially
        slide.classList.remove('active-slide', 'next-slide', 'previous-slide');
    });

    // Show the current slide and add the active class
    slides[slideIndex - 1].style.display = "flex";
    slides[slideIndex - 1].classList.add('active-slide');

    // Add the next and previous classes to the neighboring slides
    const previousIndex = (slideIndex - 2 + totalSlides) % totalSlides;
    slides[previousIndex].style.display = "flex";
    slides[previousIndex].classList.add('previous-slide');

    const nextIndex = slideIndex % totalSlides;
    slides[nextIndex].style.display = "flex";
    slides[nextIndex].classList.add('next-slide');

    // Store the last slide index in sessionStorage
    storeLastSlide(lightboxId, slideIndex);
}

// Function to change slides (use slideIndex properly)
function changeSlide(lightboxId, n) {
    const slides = document.getElementsByClassName(`slide${lightboxId}`);

    slideIndex += n; // Increment or decrement slideIndex

    if (slideIndex < 1) {
        slideIndex = slides.length;
    } else if (slideIndex > slides.length) {
        slideIndex = 1;
    }

    showSlide(lightboxId, slideIndex); // Call showSlide with correct lightboxId and slideIndex
    sessionStorage.setItem(`slideIndex_${lightboxId}`, slideIndex); // Store the new slideIndex in sessionStorage
    document.dispatchEvent(new Event("slideChange"));
}


// Function to set up key events for navigation
function setKeys(lightboxId) {
    window.onkeydown = function(e) {
        const key = e.key || e.code;

        if (key === "Escape") {
            closeLightbox(lightboxId);
        } else if (key === "ArrowRight") {
            changeSlide(lightboxId, 1);
        } else if (key === "ArrowLeft") {
            changeSlide(lightboxId, -1);
        }
    };
}

// Initialize the pointer interaction
function setupPointer() {
    const Xmax = getHighestLightboxNumber();
    const pointerElement = document.getElementById("before-pointer");

    pointerElement.onclick = function() {
        openLightbox(Xmax);
        showSlide(Xmax, slideIndex); // Start from the last known slide
    };
}

// Function to get the highest lightbox number
function getHighestLightboxNumber() {
    const lightboxes = document.querySelectorAll('[id^="Lightbox_"]');
    let highest = 0;
    lightboxes.forEach((lightbox) => {
        const id = lightbox.id;
        const number = parseInt(id.replace("Lightbox_", ""));
        if (number > highest) highest = number;
    });
    return highest;
}